<script setup lang="ts">
import {collectionItems} from '../../../../api/src/core/decoration-components.mjs'
import type {DecorationBlock,DecorationLink,DecorationApplicationComponent} from '../../../../api/src/core/decoration-types'
const props=defineProps<{block:DecorationBlock;component:DecorationApplicationComponent;editable?:boolean;imageUrl:(id:string)=>string}>()
const items=computed(()=>collectionItems(props.block,props.component))
const emit=defineEmits<{navigate:[target:DecorationLink]}>()
let start:number|null=null,origin=0,moved=false
function down(event:MouseEvent){if(props.editable||event.button!==0)return;start=event.clientX;origin=(event.currentTarget as HTMLElement).scrollLeft;moved=false}
function move(event:MouseEvent){if(start===null)return;const delta=event.clientX-start;if(Math.abs(delta)>6)moved=true;if(moved){event.preventDefault();(event.currentTarget as HTMLElement).scrollLeft=origin-delta}}
function step(event:KeyboardEvent,delta:number){(event.currentTarget as HTMLElement).scrollLeft+=delta}
function go(target:DecorationLink){if(props.editable)return;if(moved){moved=false;return}emit('navigate',target)}
</script>
<template>
 <div class="collection">
  <div class="collection-heading"><div class="collection-heading-copy"><span class="collection-title">{{block.title}}</span><span v-if="block.text" class="collection-description" :title="block.text">{{block.text}}</span></div><button v-if="block.target&&block.options?.showMore!==false" type="button" @click="go(block.target)">{{block.options?.moreText||'查看全部'}} <span aria-hidden="true">›</span></button></div>
  <div v-if="items.length" class="collection-scroll" tabindex="0" :aria-label="block.title" @mousedown="down" @mousemove="move" @mouseup="start=null" @mouseleave="start=null" @keydown.left.prevent="step($event,-144)" @keydown.right.prevent="step($event,144)">
   <div class="collection-items"><button v-for="item in items" :key="item.id" type="button" class="collection-item" :style="{width:'calc(var(--diy-unit,1px) * '+(block.options?.collectionWidth||71)+')'}" @click="go(item.target)"><img v-if="item.image" class="collection-photo" :style="{width:'calc(var(--diy-unit,1px) * '+((block.options?.collectionWidth||71)-12)+')',height:'calc(var(--diy-unit,1px) * '+(block.options?.collectionImageHeight||77)+')'}" :src="imageUrl(item.image)" alt="示例图片" :draggable="false"/><span class="item-title">{{item.title}}</span><span class="item-description">{{item.text}}</span></button></div>
  </div>
  <div v-else class="collection-empty" role="status">{{component.emptyText}}</div>
  <span v-if="component.note" class="collection-note">{{component.note}}</span>
 </div>
</template>
<style scoped>
.collection{color:inherit;text-align:left}.collection-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:calc(var(--diy-unit, 1px) * 8);margin-bottom:calc(var(--diy-unit, 1px) * 14)}.collection-title{display:block;font-size:calc(var(--diy-unit, 1px) * 16);font-weight:650;line-height:1.5}.collection-description{display:block;margin-top:calc(var(--diy-unit, 1px) * 3);font-size:calc(var(--diy-unit, 1px) * 12);color:var(--client-muted,#64748b);line-height:1.6}.collection button{margin:0;padding:0;border:0;background:transparent;color:inherit;font:inherit;line-height:1.5}.collection button::after{border:0}.collection-heading button{flex-shrink:0;white-space:nowrap;font-size:calc(var(--diy-unit, 1px) * 12);color:var(--client-muted,#64748b);padding:calc(var(--diy-unit, 1px) * 3) 0}.collection-heading button span{font-size:calc(var(--diy-unit, 1px) * 15);margin-left:calc(var(--diy-unit, 1px) * 2)}.collection-scroll{width:100%;white-space:nowrap;cursor:grab}.collection-items{display:flex;gap:calc(var(--diy-unit, 1px) * 10);padding:calc(var(--diy-unit, 1px) * 1) 0 calc(var(--diy-unit, 1px) * 4)}.collection .collection-item{display:flex;flex-shrink:0;flex-direction:column;width:calc(var(--diy-unit, 1px) * 122);padding:calc(var(--diy-unit, 1px) * 12);box-sizing:border-box;white-space:normal;text-align:left;border:calc(var(--diy-unit, 1px) * 1) solid #e7edf5;border-radius:calc(var(--diy-unit, 1px) * 10);background:var(--client-background,#f5f7fb);user-select:none}.collection-item:active{border-color:var(--client-primary,#2563eb)}.item-title{font-size:calc(var(--diy-unit, 1px) * 14);font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%}.item-description{font-size:calc(var(--diy-unit, 1px) * 11.5);margin-top:calc(var(--diy-unit, 1px) * 4);white-space:nowrap;color:var(--client-muted,#64748b)}.collection-note{display:block;font-size:calc(var(--diy-unit, 1px) * 10.5);line-height:1.6;color:var(--client-muted,#64748b);margin-top:calc(var(--diy-unit, 1px) * 10);white-space:normal}.collection-empty{padding:calc(var(--diy-unit, 1px) * 20) 0;font-size:calc(var(--diy-unit, 1px) * 13);color:var(--client-muted,#64748b)}

.collection-scroll{overflow-x:auto;scrollbar-width:none}.collection-scroll::-webkit-scrollbar{display:none}
.collection-heading{margin-bottom:calc(var(--diy-unit,1px)*9)}.collection .collection-item{width:calc(var(--diy-unit,1px)*71);padding:0;border:0;border-radius:0;background:transparent;align-items:center;text-align:center}.collection-photo{display:block;width:calc(var(--diy-unit,1px)*59);height:calc(var(--diy-unit,1px)*77);padding:0;border:0;border-radius:0;box-sizing:border-box;background:transparent;margin-bottom:calc(var(--diy-unit,1px)*5);object-fit:cover}.item-title{font-size:calc(var(--diy-unit,1px)*12.5)}.item-description{font-size:calc(var(--diy-unit,1px)*10);margin-top:calc(var(--diy-unit,1px)*2)}.collection-items{gap:calc(var(--diy-unit,1px)*8)}.collection-note{font-size:calc(var(--diy-unit,1px)*9);margin-top:calc(var(--diy-unit,1px)*7)}.collection-heading{align-items:center}.collection-heading-copy{display:flex;align-items:baseline;gap:calc(var(--diy-unit,1px)*8);min-width:0;flex:1}.collection-title{flex-shrink:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.collection-description{display:block;min-width:0;margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:calc(var(--diy-unit,1px)*11);line-height:1.5;color:var(--client-muted,#8090a4)}</style>
